import http from 'node:http';
http.createServer((req,res)=>{res.setHeader('Content-Type','text/html;charset=utf-8');res.end(`<!doctype html><title>Persistence fixture</title><style>body{font:25px sans-serif;background:white;color:black}button{position:fixed;left:200px;top:300px;width:500px;height:90px;font:26px sans-serif}pre{position:fixed;left:50px;top:430px}</style><h1>Controlled persistence fixture — no real login</h1><button id="save-state">保存受控测试状态</button><pre id="state"></pre><script>const key=new URL(location.href).searchParams.get('case');const show=()=>document.querySelector('#state').textContent=JSON.stringify({persistentCookie:document.cookie.split('; ').find(x=>x.startsWith('persistent_'+key+'='))??null,sessionCookie:document.cookie.split('; ').find(x=>x.startsWith('session_'+key+'='))??null,localStorage:localStorage.getItem(key)},null,2);document.querySelector('#save-state').onclick=()=>{document.cookie='persistent_'+key+'=test_value;path=/;max-age=86400';document.cookie='session_'+key+'=test_value;path=/';localStorage.setItem(key,'test_value');document.querySelector('#save-state').style.background='#008000';show()};show();</script>`)}).listen(8086,'0.0.0.0');
